            unsigned a=static_cast<unsigned char>(input[i]);
            unsigned b=i+1<input.size()?static_cast<unsigned char>(input[i+1]):0;
            unsigned c=i+2<input.size()?static_cast<unsigned char>(input[i+2]):0;
